import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"

def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")
    data = []
    start_time = time.time()
    while time.time() - start_time < duration:
        timestamp = time.time()
        if platform.system() == "Windows":
            cmd = ["wmic", "cpu", "get", "loadpercentage"]
        else:
            cmd = ["top", "-bn1"]
        try:
            output = subprocess.check_output(cmd, stderr=subprocess.DEVNULL)
            if platform.system() == "Windows":
                usage = float(output.decode().strip().split("\n")[1].strip())
            else:
                lines = output.decode().split("\n")
                for line in lines:
                    if "%Cpu(s)" in line:
                        usage = float(line.split()[1])
                        break
        except Exception:
            usage = 0.0
        data.append({"timestamp": timestamp, "cpu_usage": usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

